## 7. 经典例题

### 7.1 阶乘计算

**问题：** 计算 $n!$（$n \leq 1000$）

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> mul(vector<int> &A, int b) {
    vector<int> C;
    int carry = 0;
    for (int i = 0; i < A.size() || carry; i++) {
        if (i < A.size()) carry += A[i] * b;
        C.push_back(carry % 10);
        carry /= 10;
    }
    return C;
}

int main() {
    int n;
    cin >> n;

    vector<int> result = {1};  // 初始化为 1

    // 计算 n!
    for (int i = 2; i <= n; i++) {
        result = mul(result, i);
    }

    // 输出结果
    for (int i = result.size() - 1; i >= 0; i--) 
        cout << result[i];
    cout << endl;

    return 0;
}
```

